begin;
set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table tecnica_test(actor uuid,company_id uuid,order_id uuid,pos_id uuid,contenuto jsonb);
insert into tecnica_test select sp.user_id,sp.company_id,o.id,gen_random_uuid(),null from public.staff_permissions sp join public.orders o on o.company_id=sp.company_id where sp.can_view_sicurezza_cantiere and not sp.sola_lettura and public.has_permission_for_company(sp.user_id,'can_edit_mezzi',sp.company_id) and o.deleted_at is null and exists(select 1 from public.orders x where x.company_id=o.company_id and x.id<>o.id and x.deleted_at is null) limit 1;
grant select on tecnica_test to authenticated,service_role;
do $$begin if not exists(select 1 from tecnica_test) then raise exception 'Azienda di prova assente';end if;end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from tecnica_test;
update tecnica_test set contenuto='{"versione_modello": 1, "versione_controlli": 2, "versione_tecnica": 1, "formazione": [], "lavorazioni": [{"id": "l1", "titolo": "TEST SCHEDA TECNICA", "tecnica": {"area": "TEST area", "interferenze": "TEST interferenze", "condizioni_avvio": "TEST condizioni_avvio", "sospensione": "TEST sospensione", "emergenze": "TEST emergenze", "prima": "TEST prima", "durante": "TEST durante", "dopo": "TEST dopo", "riesaminata": true, "attrezzature_previste": "si", "motivo_senza_attrezzature": "", "rischi": [{"id": "r1", "pericolo": "TEST pericolo", "esposti": "TEST esposti", "situazione": "TEST situazione", "valutazione_iniziale": "TEST valutazione_iniziale", "misure_collettive": "TEST misure_collettive", "misure_organizzative": "TEST misure_organizzative", "dpi": "TEST dpi", "valutazione_residua": "TEST valutazione_residua", "riferimento": "TEST riferimento"}], "attrezzature": [{"id": "a1", "nome": "TEST nome", "identificativo": "TEST identificativo", "impiego": "TEST impiego", "controlli_preuso": "TEST controlli_preuso", "manuale_riferimento": "TEST manuale_riferimento", "formazione_addestramento": "TEST formazione_addestramento"}]}}]}'::jsonb;
create temporary table mezzo_test(a1 uuid default gen_random_uuid(),a2 uuid default gen_random_uuid(),q uuid default gen_random_uuid(),parent uuid default gen_random_uuid(),child uuid default gen_random_uuid(),fuori uuid default gen_random_uuid(),altro uuid,fonte jsonb,prova jsonb);
insert into mezzo_test(altro)select id from public.orders where company_id=(select company_id from tecnica_test) and id<>(select order_id from tecnica_test) and deleted_at is null limit 1;
grant select on mezzo_test to authenticated,service_role;
insert into public.mezzi(id,company_id,nome,tipo,assegnato_order_id,matricola,note,valore_acquisto)
select v.id,f.company_id,'TEST MEZZI POS OMONIMO',v.tipo,v.ordine,v.id::text,'TEST NOTA PRIVATA',999 from tecnica_test f cross join mezzo_test t cross join lateral(values(t.a1,'attrezzatura',f.order_id),(t.a2,'attrezzatura',f.order_id),(t.parent,'furgone',f.order_id),(t.fuori,'attrezzatura',t.altro))v(id,tipo,ordine);
update public.mezzi_assegnazioni set dal='2026-11-01 00:00 Europe/Rome',al='2026-12-01 00:00 Europe/Rome' where mezzo_id=(select a1 from mezzo_test);
-- Legacy current placement has no historical assignment. Never edit real rows.
delete from public.mezzi_assegnazioni where mezzo_id=(select a2 from mezzo_test);
insert into public.mezzi(id,company_id,nome,tipo,su_mezzo_id) select t.child,f.company_id,'TEST MEZZI POS CARICATO','attrezzatura',t.parent from tecnica_test f cross join mezzo_test t;
insert into public.mezzi(id,company_id,nome,tipo,gestione,quantita_totale,unita_misura) select t.q,f.company_id,'TEST MEZZI POS QUANTITA','attrezzatura','quantita',10,'mq' from tecnica_test f cross join mezzo_test t;
insert into public.mezzi_allocazioni(company_id,mezzo_id,order_id,quantita,dal,al) select f.company_id,t.q,f.order_id,2.5,'2026-11-01','2026-11-30' from tecnica_test f cross join mezzo_test t;
update mezzo_test set fonte=(select public.pos_mezzo_fotografia(f.company_id,f.order_id,t.a1,'assegnazione',a.id) from tecnica_test f cross join mezzo_test t join public.mezzi_assegnazioni a on a.mezzo_id=t.a1);
update tecnica_test set contenuto=contenuto||jsonb_build_object('versione_mezzi',1,'opera',jsonb_build_object('data_inizio','2026-11-01','data_fine','2026-11-30'));
update tecnica_test set contenuto=jsonb_set(contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica}',jsonb_build_object('modalita','inventario','motivazione','','fonte',(select fonte from mezzo_test),'utilizzo_dal','2026-11-02','utilizzo_al','2026-11-20','quantita_usata',1,'confermata',true));

create temporary table verbale_test(intervento uuid default gen_random_uuid(),richiesta uuid default gen_random_uuid(),tentativo uuid default gen_random_uuid(),foto jsonb,parametri jsonb,copia text,ricevuta jsonb);
insert into verbale_test(parametri) values('{"titolo":"TEST VERBALE TECNICO","categoria":"verifica_periodica","data_inizio":"2026-11-01","data_scadenza":"2027-11-01","conferma_tecnica":true}');grant select on verbale_test to authenticated,service_role;grant update on verbale_test to service_role;
insert into public.mezzi_manutenzioni(id,company_id,mezzo_id,tipo,data,file_path,file_name,costo,descrizione)select v.intervento,f.company_id,t.a1,'verifica','2026-11-01',f.company_id::text||'/'||t.a1::text||'/w-originale.pdf','TEST VERBALE.pdf',9876,'TEST NOTA RISERVATA' from verbale_test v cross join tecnica_test f cross join mezzo_test t;
insert into storage.objects(bucket_id,name,version,metadata)select 'mezzi-documenti',f.company_id::text||'/'||t.a1::text||'/w-originale.pdf','TEST-W-1','{"eTag":"TEST","size":10}'::jsonb from tecnica_test f cross join mezzo_test t;
update verbale_test v set foto=public.mezzi_verbale_fonte(f.company_id,t.a1,v.intervento,f.actor),copia=f.company_id::text||'/'||t.a1::text||'/'||v.richiesta::text||'-'||v.tentativo::text||'-test.pdf' from tecnica_test f cross join mezzo_test t;
insert into storage.objects(bucket_id,name,version,metadata)select 'mezzi-documenti',copia,'TEST-COPIA','{"eTag":"TEST","size":10}'::jsonb from verbale_test;
set local role service_role;
do $$declare f record;t record;v record;r jsonb;begin select * into f from tecnica_test;select * into t from mezzo_test;select * into v from verbale_test;
 if v.foto::text like '%costo%' or v.foto::text like '%9876%' or v.foto::text like '%TEST NOTA RISERVATA%' then raise exception 'ASSERT: dati economici/privati nel documento';end if;
 begin perform public.mezzi_verbale_fonte(f.company_id,t.a2,v.intervento,f.actor);raise exception 'ASSERT: altra macchina';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.mezzi_verbale_fonte(f.company_id,t.a1,v.intervento,gen_random_uuid());raise exception 'ASSERT: autore senza modifica Mezzi';exception when insufficient_privilege then null;end;
 begin perform public.mezzi_verbale_completa(f.company_id,t.a1,v.intervento,v.richiesta,v.foto->'foto'->>'impronta',jsonb_set(v.parametri,'{conferma_tecnica}','false'),f.actor,v.tentativo,v.copia,repeat('a',64),10);raise exception 'ASSERT: classificazione implicita';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.mezzi_verbale_completa(f.company_id,t.a1,v.intervento,v.richiesta,v.foto->'foto'->>'impronta',v.parametri,f.actor,v.tentativo,v.foto->>'path',repeat('a',64),10);raise exception 'ASSERT: originale riusato come copia';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
end$$;
reset role;
do $$declare f record;t record;v record;begin select * into f from tecnica_test;select * into t from mezzo_test;select * into v from verbale_test;
 begin update storage.objects set version='TEST-W-2' where bucket_id='mezzi-documenti' and name=v.foto->>'path';perform public.mezzi_verbale_completa(f.company_id,t.a1,v.intervento,v.richiesta,v.foto->'foto'->>'impronta',v.parametri,f.actor,v.tentativo,v.copia,repeat('a',64),10);raise exception 'ASSERT: fonte cambiata';exception when serialization_failure then null;end;
end$$;
set local role service_role;
update verbale_test v set ricevuta=public.mezzi_verbale_completa(f.company_id,t.a1,v.intervento,v.richiesta,v.foto->'foto'->>'impronta',v.parametri,f.actor,v.tentativo,v.copia,repeat('a',64),10)from tecnica_test f cross join mezzo_test t;
set local role service_role;
do $$declare f record;t record;v record;r jsonb;begin select * into f from tecnica_test;select * into t from mezzo_test;select * into v from verbale_test;
 r:=public.mezzi_verbale_completa(f.company_id,t.a1,v.intervento,v.richiesta,v.foto->'foto'->>'impronta',v.parametri,f.actor,gen_random_uuid(),'non/caricata.pdf',repeat('b',64),10);
 if r->>'documento_id' is distinct from v.ricevuta->>'documento_id' or (select count(*) from public.mezzi_verbali_tecnici where id=v.richiesta)<>1 then raise exception 'ASSERT: ritentativo duplicato';end if;
 begin perform public.mezzi_verbale_copia_esistente(f.company_id,t.a1,v.intervento,v.richiesta,v.foto->'foto'->>'impronta',jsonb_set(v.parametri,'{titolo}','"ALTRO TITOLO"'),f.actor);raise exception 'ASSERT: stessa richiesta nuovi parametri';exception when serialization_failure then null;end;
end$$;
reset role;
-- The independent document is preserved after removing the intervention row.
-- Physical Storage deletion is not simulated through SQL: the API enforces that boundary.
delete from public.mezzi_manutenzioni where id=(select intervento from verbale_test);
set local role service_role;
do $$declare f record;t record;v record;r jsonb;d public.mezzi_documenti;begin select * into f from tecnica_test;select * into t from mezzo_test;select * into v from verbale_test;
 r:=public.mezzi_verbale_copia_esistente(f.company_id,t.a1,v.intervento,v.richiesta,v.foto->'foto'->>'impronta',v.parametri,f.actor);
 if r->'disponibile' is distinct from 'true'::jsonb then raise exception 'ASSERT: copia dipende dall’originale';end if;
 select * into d from public.mezzi_documenti where id=(r->>'documento_id')::uuid;
 if d.importo is not null or d.note is not null or d.file_path=(v.foto->>'path') or public.pos_documento_mezzo_foto(d)->'disponibile' is distinct from 'true'::jsonb then raise exception 'ASSERT: documento non selezionabile nel POS o dati privati copiati';end if;
end$$;
reset role;
set local role authenticated;
do $$declare f record;t record;q jsonb;begin select * into f from tecnica_test;select * into t from mezzo_test;
 q:=public.mezzi_verbali_tecnici_elenco(f.company_id,t.a1);
 if q->'registrazioni'->0->>'data_intervento' is distinct from '2026-11-01' then raise exception 'ASSERT: data dell’intervento perduta';end if;
 if jsonb_array_length(q->'registrazioni')<>1 or q::text like '%copia_path%' or q::text like '%origine_path%' or q::text like '%fonte_snapshot%' then raise exception 'ASSERT: registro pubblico non minimizzato';end if;
 if has_table_privilege('authenticated','public.mezzi_verbali_tecnici','SELECT') or has_function_privilege('authenticated','public.mezzi_verbale_completa(uuid,uuid,uuid,uuid,text,jsonb,uuid,uuid,text,text,integer)','execute') then raise exception 'ASSERT: scrittura/registro interno esposti';end if;
 begin perform public.mezzi_verbali_tecnici_elenco(gen_random_uuid(),t.a1);raise exception 'ASSERT: registro altra azienda';exception when insufficient_privilege then null;end;
end$$;
reset role;
select 'PASS: classificazione, ambito, copia indipendente, idempotenza, fonte cambiata, privacy e selezione POS; solo metadata con rollback' as risultato;
rollback;
